def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def act1(n): return ' Sólo puedes activar 1 "%s" por turno.' % n
H = '"HERO"'
EH = '"Elemental HERO"'
EV = '"Evil HERO"'
DF = '"Dark Fusion"'
MC = '"Mask Change"'
DH = '"Destiny HERO"'
DFS = 'Debe ser Invocada de Modo Especial con ' + DF + '. '
CONTACT = 'Primero debe ser Invocada de Modo Especial (desde tu Extra Deck) barajando en el Deck las cartas anteriores que controles. (No usas "Polymerization".) '
ES = {
"Evil HERO Toxic Bubble": 'Puedes Invocar esta carta de Modo Especial (desde tu mano), pero durante el resto de este turno no puedes Invocar de Modo Especial, excepto monstruos ' + H + '. Sólo puedes Invocar de Modo Especial "Evil HERO Toxic Bubble" de esta forma una vez por turno. Si esta carta es Invocada de Modo Especial, y controlas un Monstruo de Fusión que deba ser Invocado de Modo Especial con ' + DF + ': puedes robar 2 cartas.' + once("Evil HERO Toxic Bubble"),
"Elemental HERO Marine Neos": '"Elemental HERO Neos" + "Neo-Spacian Marine Dolphin"\n' + CONTACT + 'Una vez por turno: puedes destruir 1 carta al azar de la mano de tu adversario.',
"Elemental HERO Neo Bubbleman": 'Esta carta no puede ser Invocada de Modo Normal ni Colocada. Esta carta no puede ser Invocada de Modo Especial, excepto mandando al Cementerio un "Elemental HERO Bubbleman" que controles y "Metamorphosis" de tu mano. El nombre de esta carta se trata como "Elemental HERO Bubbleman" mientras esté boca arriba en el Campo. Destruye al final del Damage Step un monstruo del adversario que combata con esta carta.',
"Elemental HERO Clay Guardian": '1 monstruo ' + EH + ' + 1 monstruo de Tipo Guerrero\n(Esta carta no se trata como una carta "Guardian".)\nSi esta carta es Invocada de Modo Especial: puedes Invocar de Modo Especial 1 monstruo ' + EH + ' de tu Deck y, después, si tu adversario controla alguna carta, puedes infligirle 400 de daño por cada una; además, durante el resto de este turno no puedes Invocar de Modo Especial desde el Extra Deck, excepto monstruos ' + H + '.' + once("Elemental HERO Clay Guardian") + ' Los demás monstruos ' + EH + ' que controles no pueden ser destruidos en batalla ni por efectos de cartas.',
"Elemental HERO Voltic": 'Cuando esta carta inflija daño de batalla a tu adversario: puedes seleccionar 1 de tus monstruos ' + EH + ' desterrados; Invoca de Modo Especial ese objetivo.',
"Masked HERO Dusk Crow": 'Si esta carta está en tu mano: puedes desterrar 1 monstruo ' + H + ' de tu Cementerio; Invoca esta carta de Modo Especial. Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 monstruo "Masked HERO" de tu Deck o Cementerio, excepto "Masked HERO Dusk Crow".' + each("Masked HERO Dusk Crow"),
"Masked HERO Vapor": 'Debe ser Invocada de Modo Especial con ' + MC + '. No puede ser destruida por efectos de cartas.',
"Favorite HERO Flame Wingman": '2 monstruos del mismo Tipo pero de Atributos diferentes\n(Esta carta se trata siempre como una carta ' + EH + '.)\nCuando se declare un ataque que involucre a esta carta y a un monstruo con 2200 o más ATK: puedes hacer que esta carta gane 1000 ATK y, después, puedes Invocar de Modo Especial 1 monstruo de Nivel 4 o menor de tu mano en Posición de Defensa. Si uno o más monstruos fueron destruidos en batalla este turno (Efecto Rápido): puedes Invocar por Fusión 1 Monstruo de Fusión desde tu Extra Deck, usando monstruos de tu mano o Campo.' + each("Favorite HERO Flame Wingman"),
"Evil HERO Wild Cyclone": '"Elemental HERO Avian" + "Elemental HERO Wildheart"\n' + DFS + 'Si esta carta ataca, tu adversario no puede activar Cartas Mágicas/de Trampa hasta el final del Damage Step. Si esta carta inflige daño de batalla a tu adversario: destruye todas las Mágicas/Trampas Colocadas que controle tu adversario.',
"Evil HERO Adusted Gold": 'Puedes descartar esta carta; añade a tu mano desde tu Deck 1 ' + DF + ', o 1 carta que lo mencione, excepto "Evil HERO Adusted Gold".' + once("Evil HERO Adusted Gold") + ' No puede atacar a menos que controles un Monstruo de Fusión.',
"Evil HERO Neos Lord": '"Elemental HERO Neos" (o 1 Monstruo de Fusión que lo mencione) + 1 Monstruo de Efecto en el Campo\n' + DFS + 'No puede ser destruida en batalla ni por efectos de cartas. Si esta carta es Invocada de Modo Especial, o uno o más monstruos son mandados al Cementerio de tu adversario mientras esta carta está en el Campo: puedes seleccionar 1 monstruo boca arriba que controle tu adversario; toma el control de él.' + once("Evil HERO Neos Lord"),
"Elemental HERO Chaos Neos": '"Elemental HERO Neos" + "Neo-Spacian Dark Panther" + "Neo-Spacian Glow Moss"\n' + CONTACT + 'Una vez por turno, durante la End Phase: baraja esta carta en el Extra Deck y, si lo haces, Coloca todos los monstruos boca arriba en el Campo. Una vez por turno, durante tu Main Phase 1: puedes lanzar una moneda 3 veces.\n● 3 Caras: destruye todos los monstruos que controle tu adversario.\n● 2 Caras: durante el resto de este turno, los efectos de todos los monstruos boca arriba que controle tu adversario quedan negados.\n● 1 Cara: devuelve a la mano todos los monstruos que controles.',
"Elemental HERO Thunder Giant - Voltic Thunder": '2 monstruos ' + EH + ' con Atributos diferentes\nDebe ser Invocada por Fusión. Si esta carta es Invocada de Modo Especial y tu adversario controla más cartas que tú: puedes destruir todas las demás cartas en el Campo. Puedes Sacrificar esta carta que fue Invocada por Fusión usando uno o más Monstruos Normales como material y, después, seleccionar 1 monstruo ' + EH + ' en tu Cementerio; Invócalo de Modo Especial.' + each("Elemental HERO Thunder Giant - Voltic Thunder"),
"Evil HERO Lightning Golem": '"Elemental HERO Sparkman" + "Elemental HERO Clayman"\n' + DFS + 'Una vez por turno: puedes seleccionar 1 monstruo en el Campo; destruye ese objetivo.',
"Masked HERO Divine Wind": 'Debe ser Invocada de Modo Especial con ' + MC + ' y no puede ser Invocada de Modo Especial de otras formas. No puede ser destruida en batalla. Tu adversario sólo puede atacar con 1 monstruo durante cada Battle Phase. Cuando esta carta destruya en batalla un monstruo del adversario y lo mande al Cementerio: puedes robar 1 carta.',
"Evil HERO Inferno Wing": '"Elemental HERO Avian" + "Elemental HERO Burstinatrix"\n' + DFS + 'Si esta carta ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración. Si esta carta destruye en batalla un monstruo y lo manda al Cementerio: inflige a tu adversario daño igual al ATK o la DEF original (lo que sea mayor) de ese monstruo en el Cementerio.',
"Contrast HERO Chaos": '2 monstruos "Masked HERO"\n(Esta carta se trata siempre como una carta ' + EH + '.)\nDebe ser Invocada por Fusión y no puede ser Invocada de Modo Especial de otras formas. Mientras esté boca arriba en el Campo, esta carta también es de Atributo LUZ. Una vez por turno, durante el turno de cualquier jugador: puedes seleccionar 1 carta boca arriba en el Campo; niega los efectos de ese objetivo hasta el final de este turno.',
"Legacy of a HERO": 'Devuelve al Extra Deck 2 Monstruos de Fusión de tu Cementerio que indiquen un monstruo ' + H + ' como Material; roba 3 cartas.' + act1("Legacy of a HERO"),
"Destiny HERO - Dark Angel": 'Si tienes 3 o más monstruos ' + DH + ' en tu Cementerio: puedes descartar esta carta y, después, seleccionar 1 monstruo ' + DH + ' en tu Cementerio; Invócalo de Modo Especial en el Campo de tu adversario en Posición de Defensa. Cuando se resuelva una Carta Mágica o efecto de Mágica que actives, niega ese efecto y, si lo haces, o si no tenía efecto, destruye esa carta. Durante tu Standby Phase: puedes desterrar esta carta y 1 monstruo ' + DH + ' de tu Cementerio; cada jugador elige 1 Mágica Normal de su Deck y la coloca en la parte superior de su Deck.',
"Evil HERO Dead-End Prison": 'Si controlas un Monstruo de Fusión que deba ser Invocado de Modo Especial con ' + DF + ', puedes Invocar esta carta de Modo Especial (desde tu mano). Sólo puedes Invocar de Modo Especial "Evil HERO Dead-End Prison" de esta forma una vez por turno. Puedes mandar al Cementerio 1 monstruo ' + H + ' de tu Deck; si Invocas por Fusión un monstruo ' + H + ' este turno, esta carta boca arriba puede ser usada en lugar de 1 material mencionado por su nombre, pero todos los demás Materiales de Fusión deben ser los correctos.' + once("Evil HERO Dead-End Prison"),
"Miracle Ejector": '(Esta carta se trata siempre como una carta ' + EH + '.)\nSi esta carta está en tu mano: puedes mandar al Cementerio 1 monstruo "Neo-Spacian" de tu Deck; Invoca esta carta de Modo Especial. Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano desde tu Deck 1 Mágica/Trampa que mencione el nombre de un monstruo ' + EH + '. Si esta carta es mandada al Cementerio: puedes seleccionar 1 carta en el Cementerio de tu adversario; destiérrala.' + each("Miracle Ejector"),
"Evil HERO Vicious Claws": 'Puedes seleccionar 1 monstruo ' + H + ' en el Campo; Invoca esta carta de Modo Especial desde tu mano en Posición de Defensa y, si lo haces, ese monstruo gana 300 ATK.' + once("Evil HERO Vicious Claws") + ' Si uno o más monstruos que controlas son destruidos en batalla o por un efecto de carta, mientras esta carta está en tu Cementerio: puedes Invocar esta carta de Modo Especial y, después, si tienes en tu Cementerio un monstruo que mencione ' + DF + ', puedes destruir 1 carta en el Campo. Sólo puedes usar este efecto de "Evil HERO Vicious Claws" una vez por Duelo.',
"Destiny HERO - Dread Servant": 'Si esta carta es Invocada de Modo Normal: pon 1 Contador de Reloj en cada "Clock Tower Prison". Cuando esta carta sea destruida en batalla y mandada al Cementerio: puedes seleccionar 1 Mágica/Trampa que controles; destruye ese objetivo.',
"Elemental HERO Grandmerge": '2 Monstruos Normales ' + H + '\nDebe ser Invocada por Fusión. Gana ATK/DEF igual a los Niveles originales combinados de los materiales usados para su Invocación por Fusión x 300. Cuando esta carta destruya en batalla un monstruo del adversario: puedes Sacrificar esta carta; Invoca de Modo Especial 1 Monstruo de Fusión ' + EH + ' desde tu Extra Deck, ignorando sus condiciones de Invocación, pero no puede atacar a monstruos con un Nivel igual o menor que el suyo.',
"Elemental HERO Ocean": 'Una vez por turno, durante tu Standby Phase: puedes seleccionar 1 monstruo ' + H + ' que controles o que esté en tu Cementerio; devuelve ese objetivo a la mano.',
"Elemental HERO Nebula Neos": '"Elemental HERO Neos" + "Neo-Spacian Grand Mole" + "Neo-Spacian Dark Panther"\n' + CONTACT + 'Si esta carta es Invocada de Modo Especial desde el Extra Deck: roba tantas cartas como cartas controle tu adversario y, después, niega los efectos de 1 carta boca arriba en el Campo hasta el final de este turno. Una vez por turno, durante la End Phase: baraja esta carta en el Extra Deck y, si lo haces, destierra boca abajo todas las cartas en el Campo.',
"Elemental HERO Ice Edge": 'Cuando esta carta inflija daño de batalla a tu adversario con un ataque directo: puedes seleccionar 1 carta Colocada en la Zona de Cartas Mágicas y de Trampa de tu adversario; destruye ese objetivo. Una vez por turno, durante tu Main Phase 1: puedes descartar 1 carta; esta carta puede atacar directamente a tu adversario este turno.',
"Elemental HERO Darkbright": '"Elemental HERO Sparkman" + "Elemental HERO Necroshade"\nDebe ser Invocada por Fusión. Si esta carta ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración. Si esta carta ataca, cámbiala a Posición de Defensa al final del Damage Step. Si esta carta es destruida: selecciona 1 monstruo que controle tu adversario; destruye ese objetivo.',
"Evil HERO Sinister Necrom": 'Puedes desterrar esta carta de tu Cementerio; Invoca de Modo Especial 1 monstruo ' + EV + ' de tu mano o Deck, excepto "Evil HERO Sinister Necrom".' + once("Evil HERO Sinister Necrom"),
"Evil HERO Infernal Sniper": '"Elemental HERO Clayman" + "Elemental HERO Burstinatrix"\n' + DFS + 'No puede ser destruida por efectos de Mágicas. Una vez por turno, durante tu Standby Phase: inflige 1000 de daño a tu adversario. Esta carta debe estar en Posición de Defensa boca arriba para activar y resolver este efecto.',
"Evil HERO Infernal Prodigy": 'Si no controlas monstruos, puedes Invocar esta carta de Modo Especial (desde tu mano) en Posición de Ataque. Una vez por turno, durante la End Phase, si esta carta fue Sacrificada este turno para Invocar por Sacrificio un monstruo ' + H + ': roba 1 carta.',
"Masked HERO Koga": 'Debe ser Invocada de Modo Especial con ' + MC + ' y no puede ser Invocada de Modo Especial de otras formas. Esta carta gana 500 ATK por cada monstruo que controle tu adversario. Una vez por turno, durante el turno de cualquier jugador: puedes desterrar 1 monstruo ' + H + ' de tu Cementerio y, después, seleccionar 1 monstruo boca arriba en el Campo; ese objetivo pierde ATK igual al ATK del monstruo desterrado para activar este efecto, hasta el final de este turno.',
"Elemental HERO Poison Rose": 'No puede ser Invocada de Modo Normal ni Colocada. Debe ser Invocada de Modo Especial con "Rose Bud" y no puede ser Invocada de Modo Especial de otras formas. Cada vez que esta carta inflija daño de batalla a tu adversario: gana 200 ATK y pierde 200 DEF. Tu adversario sólo puede seleccionar "Elemental HERO Poison Rose" para sus ataques.',
"Vision HERO Gravito": 'Si esta carta es Invocada de Modo Normal o Especial: puedes seleccionar 1 de tus monstruos ' + H + ' desterrados; añádelo a tu mano. Puedes Sacrificar esta carta y, después, seleccionar 2 Cartas de Monstruo "Vision HERO" en tu Zona de Magia y Trampa; Invócalas de Modo Especial.' + each("Vision HERO Gravito"),
"Elemental HERO Shining Neos Wingman": '"Elemental HERO Neos" + 1 Monstruo de Fusión "Wingman"\nDebe ser Invocada por Fusión. Gana 300 ATK por cada monstruo en tu Cementerio; además, no puede ser destruida por efectos de cartas. Si esta carta es Invocada de Modo Especial: puedes destruir cartas que controle tu adversario hasta el número de Atributos diferentes entre los monstruos en el Campo.' + once("Elemental HERO Shining Neos Wingman") + ' Si esta carta destruye un monstruo en batalla: inflige a tu adversario daño igual al ATK original de ese monstruo.',
"Masked HERO Goka": 'Debe ser Invocada de Modo Especial con ' + MC + '. Gana 100 ATK por cada monstruo ' + H + ' en tu Cementerio.',
"Masked HERO Furnace": 'Puedes revelar esta carta en tu mano; añade a tu mano 1 ' + MC + ' o "Polymerization" de tu Deck y, después, descarta 1 carta. No puedes Invocar de Modo Especial desde el Extra Deck el turno en que actives este efecto, excepto monstruos ' + H + '. Si Invocas de Modo Especial uno o más Monstruos de Fusión ' + H + ' que no sean de FUEGO (excepto durante el Damage Step): puedes Invocar de Modo Especial esta carta desde tu Cementerio (si estaba ahí cuando se resolvió la Invocación) o desde tu mano (aunque no lo estuviera), pero destiérrala cuando deje el Campo.' + each("Masked HERO Furnace"),
"Evil HERO Dark Gaia": '1 monstruo de Tipo Demonio + 1 monstruo de Tipo Roca\n' + DFS + 'El ATK original de esta carta pasa a ser el ATK original combinado de los materiales usados para su Invocación por Fusión. Cuando esta carta declare un ataque: puedes cambiar a Posición de Ataque boca arriba todos los monstruos en Posición de Defensa que controle tu adversario. (Los efectos de Volteo no se activan en ese momento.)',
"Evil HERO Malicious Edge": 'Si tu adversario controla un monstruo, puedes Invocar por Sacrificio esta carta boca arriba con 1 Sacrificio. Si esta carta ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración.',
"Masked HERO Anki": 'Debe ser Invocada de Modo Especial con ' + MC + '. Esta carta puede atacar directamente, pero cuando lo haga usando este efecto, el daño de batalla infligido a tu adversario se reduce a la mitad. Cuando esta carta destruya en batalla un monstruo del adversario y lo mande al Cementerio: puedes añadir a tu mano 1 Carta Mágica Rápida "Change" de tu Deck.' + once("Masked HERO Anki"),
}
VTRAP = 'Si recibes daño de batalla o de efecto mientras esta carta está en tu Cementerio: puedes colocar esta carta de tu Cementerio en tu Zona de Magia y Trampa como Trampa Continua boca arriba. Durante la Main Phase, si esta carta se trata como una Trampa Continua: puedes Sacrificar 1 monstruo ' + H + '; Invoca esta carta de Modo Especial. Si esta carta es Invocada de Modo Especial desde la Zona de Magia y Trampa: '
ES.update({
"Evil HERO Inferno Wing - Backfire": '"Elemental HERO Avian" o "Elemental HERO Burstinatrix" + 1 monstruo ' + H + '\n' + DFS + 'Si esta carta es Invocada de Modo Especial: puedes añadir a tu mano desde tu Deck o Cementerio 1 ' + DF + ' o 1 carta que lo mencione, excepto Monstruos de Fusión. Si tu monstruo ' + H + ' destruye en batalla un monstruo del adversario: inflige 2100 de daño a tu adversario.' + each("Evil HERO Inferno Wing - Backfire"),
"Elemental HERO Plasma Vice": '"Elemental HERO Sparkman" + "Elemental HERO Bladedge"\nDebe ser Invocada por Fusión. Si esta carta ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración. Puedes descartar 1 carta y, después, seleccionar 1 monstruo en Posición de Ataque que controle tu adversario; destruye ese objetivo.',
"Vision HERO Minimum Ray": VTRAP + 'puedes destruir 1 monstruo de Nivel 4 o menor que controle tu adversario.' + each("Vision HERO Minimum Ray"),
"Elemental HERO Knospe": 'Cada vez que esta carta inflija daño de batalla a tu adversario: gana 100 ATK y pierde 100 DEF. Mientras controles otro monstruo ' + EH + ' boca arriba, tu adversario no puede seleccionar esta carta para un ataque, y esta carta puede atacar directamente a tu adversario.',
"Masked HERO Dian": 'Debe ser Invocada de Modo Especial con ' + MC + '. Cuando esta carta destruya en batalla un monstruo del adversario y lo mande al Cementerio: puedes Invocar de Modo Especial 1 monstruo ' + H + ' de Nivel 4 o menor de tu Deck.',
"Destiny HERO - Decider": 'Los monstruos de Nivel 6 o mayor que controla tu adversario no pueden seleccionar esta carta para sus ataques. Sólo puedes usar cada uno de los siguientes efectos de "Destiny HERO - Decider" una vez por Duelo.\n● Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 monstruo ' + H + ' de tu Cementerio durante la End Phase de este turno.\n● Cuando se active una carta o efecto que fuera a infligirte daño, mientras esta carta está en tu Cementerio (Efecto Rápido): devuelve esta carta a tu mano y, si lo haces, el daño de ese efecto que recibes pasa a ser 0.',
"Masked HERO Fountain": 'Puedes revelar esta carta en tu mano; Invoca de Modo Especial 1 monstruo ' + H + ' de tu mano en Posición de Defensa. Si esta carta es mandada al Cementerio por un efecto de carta, o para activar un efecto de carta: puedes Colocar 1 ' + MC + ' de tu Deck o Cementerio.' + each("Masked HERO Fountain"),
"Destiny HERO - Dreamer": 'Durante el cálculo de daño, si tu monstruo ' + DH + ' combate y esta carta está en tu Cementerio: puedes Invocar esta carta de Modo Especial y, si lo haces, tu monstruo no puede ser destruido en esa batalla; además, no recibes daño de batalla de esa batalla. Si es Invocada de esta forma, destierra esta carta cuando deje el Campo.' + once("Destiny HERO - Dreamer"),
"Elemental HERO Inferno": '"Elemental HERO Heat" + "Elemental HERO Lady Heat"\nDebe ser Invocada por Fusión y no puede ser Invocada de Modo Especial de otras formas. Si esta carta combate con un monstruo de AGUA, esta carta gana 1000 ATK sólo durante el Damage Step.',
"Elemental HERO Flash": 'Cuando esta carta sea destruida en batalla y mandada al Cementerio: puedes desterrar esta carta y 3 Cartas de Monstruo ' + EH + ' con nombres diferentes de tu Cementerio para seleccionar 1 Carta Mágica Normal en tu Cementerio; añade ese objetivo a tu mano.',
"Elemental HERO Neos Alius": 'Esta carta se trata como un Monstruo Normal mientras esté boca arriba en el Campo o en el Cementerio. Mientras esta carta sea un Monstruo Normal en el Campo, puedes Invocarla de Modo Normal para que pase a ser un Monstruo de Efecto con este efecto.\n● El nombre de esta carta pasa a ser "Elemental HERO Neos" mientras esté en el Campo.',
"Elemental HERO Neos Knight": '"Elemental HERO Neos" + 1 monstruo de Tipo Guerrero\nDebe ser Invocada por Fusión. Gana ATK igual a la mitad del ATK original del Material de Fusión de Tipo Guerrero usado para su Invocación por Fusión, excepto "Elemental HERO Neos". Puede realizar un segundo ataque durante cada Battle Phase. Tu adversario no recibe daño de batalla de los ataques que involucren a esta carta.',
"Elemental HERO Terra Firma": '"Elemental HERO Ocean" + "Elemental HERO Woodsman"\nDebe ser Invocada por Fusión y no puede ser Invocada de Modo Especial de otras formas. Puedes Sacrificar 1 monstruo ' + EH + ' boca arriba; esta carta gana ATK igual al ATK del monstruo Sacrificado, hasta la End Phase.',
"Elemental HERO Woodsman": 'Una vez por turno, durante tu Standby Phase: puedes añadir a tu mano 1 "Polymerization" de tu Deck o Cementerio.',
"HERO's Bond": 'Si hay un monstruo ' + H + ' boca arriba en el Campo: Invoca de Modo Especial 2 monstruos ' + EH + ' de Nivel 4 o menor de tu mano.',
"Evil HERO Infernal Rider": 'Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 ' + DF + ' de tu Deck o Cementerio. Puedes desterrar esta carta y otros 4 monstruos de tu Cementerio; Coloca 1 "Super Polymerization" de tu Deck; además, no puedes Invocar de Modo Especial (excepto monstruos ' + H + '), pero puedes Invocar por Fusión, usando efectos de otras cartas, monstruos que deban ser Invocados de Modo Especial con ' + DF + '. Estos efectos duran hasta el final del turno de tu adversario.' + each("Evil HERO Infernal Rider"),
"Elemental HERO Captain Gold": 'Puedes descartar esta carta al Cementerio; añade a tu mano 1 "Skyscraper" de tu Deck. Si "Skyscraper" no está boca arriba en el Campo, destruye esta carta.',
"Vision HERO Witch Raider": 'Para Invocar por Sacrificio esta carta boca arriba, puedes Sacrificar Trampas que controles, además de monstruos. Cuando esta carta sea Invocada de Modo Normal: puedes destruir todas las Mágicas y Trampas que controle tu adversario. No puedes Invocar de Modo Especial monstruos durante el turno en que actives este efecto, excepto monstruos ' + H + '.',
"Vision HERO Poisoner": VTRAP + 'puedes reducir a la mitad el ATK de 1 monstruo boca arriba en el Campo.' + each("Vision HERO Poisoner"),
"Masked HERO Atomic": 'Debe ser Invocada de Modo Especial con ' + MC + '. La primera vez que esta carta fuera a ser destruida en batalla o por un efecto de carta cada turno, no es destruida. Sólo puedes usar cada uno de los siguientes efectos de "Masked HERO Atomic" una vez por turno. Si esta carta es Invocada de Modo Especial: puedes seleccionar 1 monstruo "Masked HERO" que no sea de FUEGO en tu Cementerio o entre tus cartas desterradas; Invócalo de Modo Especial en Posición de Defensa, ignorando sus condiciones de Invocación. Durante tu End Phase: puedes seleccionar 1 Mágica Rápida "Change" en tu Cementerio; Colócala.',
"Evil HERO Malicious Bane": '1 monstruo ' + EV + ' + 1 monstruo de Nivel 5 o mayor\n' + DFS + 'No puede ser destruida en batalla ni por efectos de cartas. Durante tu Main Phase: puedes destruir todos los monstruos que controle tu adversario con ATK menor o igual al de esta carta; además, esta carta gana 200 ATK por cada monstruo destruido de esta forma; además, durante el resto de este turno no puedes declarar un ataque, excepto con monstruos ' + H + '.' + once("Evil HERO Malicious Bane"),
"Evil HERO Darkest Knight": '1 monstruo de Tipo Demonio + 1 monstruo de Tipo Guerrero\n' + DFS + 'Los monstruos que controla tu adversario pierden ATK igual al ATK original total de los materiales usados para la Invocación por Fusión de esta carta. Puede realizar un segundo ataque durante cada Battle Phase. Si esta carta Invocada de Modo Especial boca arriba bajo el control de su propietario deja el Campo por una carta del adversario: puedes seleccionar 1 monstruo de Tipo Demonio o Guerrero en tu Cementerio; Invócalo de Modo Especial en Posición de Defensa.',
"Evil HERO Malicious Fiend": '"Evil HERO Malicious Edge" + 1 monstruo de Tipo Demonio de Nivel 6 o mayor\n' + DFS + 'Durante la Battle Phase de tu adversario, todos los monstruos que controla se cambian a Posición de Ataque boca arriba, y cada monstruo que controla debe atacar a esta carta, si es posible.',
"Favorite HERO Shining Flare Wingman": '1 Monstruo de Fusión + 1 monstruo boca arriba en el Campo\n(Esta carta se trata siempre como una carta ' + EH + '.)\nSi esta carta es Invocada de Modo Especial desde el Extra Deck: puedes barajar en el Deck 5 monstruos de tu Cementerio y, después, robar 2 cartas y, si lo haces, esta carta gana 1000 ATK.' + once("Favorite HERO Shining Flare Wingman") + ' Si esta carta destruye un monstruo en batalla: inflige a tu adversario daño igual al ATK original de ese monstruo.',
"Elemental HERO Prisma": 'Una vez por turno: puedes revelar 1 Monstruo de Fusión de tu Extra Deck y, después, mandar al Cementerio desde tu Deck 1 de los Materiales de Fusión cuyo nombre aparezca específicamente en esa carta; el nombre de esta carta pasa a ser el del monstruo mandado hasta la End Phase.',
"Masked HERO Blast": 'Debe ser Invocada de Modo Especial con ' + MC + '. Si esta carta es Invocada de Modo Especial: puedes seleccionar 1 monstruo boca arriba que controle tu adversario; su ATK pasa a ser la mitad de su ATK actual. Una vez por turno (Efecto Rápido): puedes pagar 500 LP y, después, seleccionar 1 Mágica/Trampa que controle tu adversario; devuélvela a la mano.',
"Elemental HERO Cosmo Neos": '"Elemental HERO Neos" + 3 monstruos "Neo-Spacian" con Atributos diferentes\n' + CONTACT + 'Si esta carta es Invocada de Modo Especial desde el Extra Deck: puedes activar este efecto; durante el resto de este turno, tu adversario no puede activar cartas; además, las cartas que controla tu adversario no pueden activar sus efectos. Tu adversario no puede activar cartas ni efectos en respuesta a la activación de este efecto. Una vez por turno, durante la End Phase: baraja esta carta en el Extra Deck y, si lo haces, destruye todas las cartas que controle tu adversario.',
"Elemental HERO Neos Kluger": '"Elemental HERO Neos" + "Yubel"\nDebe ser Invocada por Fusión. Antes del cálculo de daño, si esta carta combate con un monstruo del adversario: puedes infligir a tu adversario daño igual al ATK de ese monstruo del adversario. Si esta carta boca arriba es destruida en batalla, o deja el Campo por un efecto de carta del adversario mientras su propietario la controla: puedes Invocar de Modo Especial 1 "Neos Wiseman" de tu mano o Deck, ignorando sus condiciones de Invocación.' + once("Elemental HERO Neos Kluger"),
"Destiny HERO - Drilldark": 'Si esta carta es Invocada de Modo Normal o Especial: puedes Invocar de Modo Especial 1 monstruo ' + DH + ' de tu mano con ATK menor o igual que el ATK de esta carta en el Campo.' + once("Destiny HERO - Drilldark") + ' Si esta carta ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración a tu adversario.',
"Elemental HERO Lady Heat": 'Durante cada una de tus End Phases: inflige a tu adversario 200 de daño por cada monstruo ' + EH + ' boca arriba que controles.',
"Elemental HERO Core": '3 monstruos ' + EH + '\nDebe ser Invocada por Fusión y no puede ser Invocada de Modo Especial de otras formas. Una vez por turno, cuando esta carta sea seleccionada para un ataque: puedes hacer que el ATK de esta carta pase a ser el doble de su ATK actual hasta el final del Damage Step. Al final de la Battle Phase, si esta carta combatió: puedes seleccionar 1 monstruo en el Campo; destrúyelo. Cuando esta carta sea destruida en batalla o por un efecto de carta: puedes seleccionar 1 Monstruo de Fusión ' + EH + ' de Nivel 8 o menor en tu Cementerio; Invócalo de Modo Especial, ignorando sus condiciones de Invocación.',
"Evil HERO Infernal Gainer": 'Durante tu Main Phase 1: puedes desterrar esta carta del Campo y, después, seleccionar 1 monstruo de Tipo Demonio que controles; ese monstruo de Tipo Demonio puede realizar un segundo ataque durante cada Battle Phase mientras permanezca boca arriba. Una vez por turno, durante tu segunda Standby Phase después de que esta carta fuera desterrada para activar este efecto: Invoca esta carta de Modo Especial en Posición de Ataque.',
"Vision HERO Multiply Guy": VTRAP + 'puedes hacer que 1 monstruo boca arriba en el Campo gane 800 ATK.' + each("Vision HERO Multiply Guy"),
"Elemental HERO Heat": 'Esta carta gana 200 ATK por cada monstruo ' + EH + ' que controles.',
"Dark Fusion": 'Invoca por Fusión 1 Monstruo de Fusión de Tipo Demonio desde tu Extra Deck, usando como Material de Fusión monstruos de tu mano o Campo. Tu adversario no puede seleccionarlo con efectos de cartas este turno.',
"Metamorphosis": 'Sacrifica 1 monstruo. Invoca de Modo Especial desde tu Extra Deck 1 Monstruo de Fusión con el mismo Nivel que el monstruo Sacrificado.',
"Rose Bud": 'Sacrifica 1 "Elemental HERO Knospe"; Invoca de Modo Especial 1 "Elemental HERO Poison Rose" de tu mano o Deck.',
})
